<template>
  <main class="shell">
    <header><div><small>ORDER AI · CUSTOMER OPERATIONS</small><h1>{{ t('title') }}</h1><p>{{ t('subtitle') }}</p></div><div class="header-actions"><label class="language-label">{{ t('language') }}<select v-model="locale"><option value="zh">中文</option><option value="en">English</option><option value="es">Español</option></select></label><span class="status"><i></i>{{ t('service') }} {{health?t('online'):t('offline')}}</span></div></header>
    <nav class="menu"><button v-for="item in menu" :key="item.id" :class="{active:page===item.id}" @click="openPage(item.id)">{{t(item.id)}}</button></nav>
    <section v-if="page==='dashboard'" class="grid">
      <article class="card inquiry"><h2>{{ t('inquiryTitle') }}</h2><p class="muted">{{ t('inquiryHelp') }}</p>
        <label>{{ t('customerEmail') }}<input v-model="form.customer_email" placeholder="customer@example.com"></label>
        <label>{{ t('subject') }}<input v-model="form.subject" :placeholder="t('subjectPlaceholder')"></label>
        <label>{{ t('inquiryContent') }}<textarea v-model="form.body" rows="5" :placeholder="t('inquiryPlaceholder')"></textarea></label>
        <button @click="classify" :disabled="busy">{{ t('classify') }}</button>
        <div v-if="inquiryResult" class="result"><span class="tag">{{ t(inquiryResult.category) }}</span> {{ t('inquirySaved') }}</div>
      </article>
      <article class="card"><h2>{{ t('customerOrders') }}</h2><p class="muted">{{ t('customerHelp') }}</p>
        <div class="row"><input v-model="email" placeholder="john@example.com"><button class="secondary" @click="lookupCustomer">{{ t('search') }}</button></div>
        <div class="customer-form"><h3>{{ t('newCustomer') }}</h3><label>{{ t('customerName') }}<input v-model="newCustomer.name" :placeholder="t('customerName')"></label><label>{{ t('customerEmail') }}<input v-model="newCustomer.email" type="email" placeholder="customer@example.com"></label><button class="secondary" @click="createCustomer" :disabled="busy">{{ t('createCustomer') }}</button></div><div v-if="customerCreated" class="result">{{ t('customerCreated') }}</div>
        <div v-if="customer" class="result"><b>{{customer.name}}</b><div>{{customer.email}}</div></div>
        <div v-for="o in orders" :key="o.order_number" class="order"><b>{{o.order_number}}</b><span>{{ t(o.status) }}</span><div>{{ t('tracking') }} {{o.tracking_number||t('notAvailable')}}</div><div v-for="i in o.items" :key="i.sku">{{i.name}} × {{i.quantity}}</div><button class="link" @click="prepareRefund(o)">{{ t('requestRefund') }}</button></div>
      </article>
      <article class="card"><h2>{{ t('productLookup') }}</h2><div class="row"><input v-model="sku" :placeholder="t('skuPlaceholder')"><button class="secondary" @click="lookupProduct">{{ t('search') }}</button></div>
        <div v-if="product" class="result"><b>{{product.name}}</b><div>SKU {{product.sku}} · {{ t('stock') }} {{product.stock}} · ¥{{product.price}}</div></div>
      </article>
      <article class="card"><h2>{{ t('refundTitle') }}</h2><p class="muted">{{ t('refundHelp') }}</p>
        <label>{{ t('orderNumber') }}<input v-model="refund.order_number" placeholder="ORD-10001"></label><label>{{ t('reason') }}<textarea v-model="refund.reason" rows="3" :placeholder="t('reasonPlaceholder')"></textarea></label>
        <button class="warm" @click="createRefund" :disabled="busy">{{ t('submitReview') }}</button>
        <div v-if="refundResult" class="result"><span class="tag pending">{{ t(refundResult.status) }}</span> {{ t('refundSubmitted') }}</div>
      </article>
    </section>
    <section v-else class="card management">
      <h2>{{t(page)}}</h2><div class="row"><input v-model="filter" :placeholder="t('filter')"><button class="secondary" @click="loadPage(0)">{{t('search')}}</button></div>
      <div v-for="row in rows" :key="row.id||row.order_number||row.sku" class="order"><b>{{row.order_number||row.sku||row.id}}</b><span>{{t(row.status||row.category||'')}}</span><div>{{row.customer_email||row.name||row.reason||row.subject}}</div><div v-if="row.stock!==undefined">{{t('stock')}} {{row.stock}} · ¥{{row.price}}</div><button v-if="page==='refunds'&&row.status==='PENDING_MANUAL_APPROVAL'" class="warm" @click="approveRefund(row.id)">{{t('approve')}}</button><button class="danger" @click="removeRow(row)">{{t('delete')}}</button></div>
      <div class="pagination"><button class="secondary" :disabled="pageNumber===0" @click="loadPage(pageNumber-1)">{{t('previous')}}</button><span>{{pageNumber+1}} / {{totalPages||1}}</span><button class="secondary" :disabled="pageNumber+1>=totalPages" @click="loadPage(pageNumber+1)">{{t('next')}}</button></div>
    </section><div v-if="error" class="toast">{{error}}</div>
  </main>
</template>
<script>
import axios from 'axios'
const messages = {
  zh: { title:'客服工作台',subtitle:'咨询处理 · 订单查询 · 退款审核',language:'语言',service:'业务服务',online:'在线',offline:'未连接',inquiryTitle:'处理客户咨询',inquiryHelp:'提交后系统将按规则分类并记录，不使用 LLM。',customerEmail:'客户邮箱',subject:'主题',subjectPlaceholder:'Where is my order?',inquiryContent:'咨询内容',inquiryPlaceholder:'请输入客户邮件内容',classify:'分类并记录',inquirySaved:'咨询已记录',customerOrders:'客户与订单',customerHelp:'使用客户邮箱查找客户及订单。',newCustomer:'新增客户',customerName:'客户姓名',createCustomer:'保存客户',customerCreated:'客户已创建',customerNotFound:'未找到该客户',customerAlreadyExists:'该邮箱已注册',search:'查询',tracking:'物流：',notAvailable:'暂无',requestRefund:'申请退款',productLookup:'商品库存查询',skuPlaceholder:'例如 MUG-001',stock:'库存',refundTitle:'退款申请',refundHelp:'此操作只创建申请，退款必须由人工审批。',orderNumber:'订单号',reason:'申请原因',reasonPlaceholder:'请描述退款原因',submitReview:'提交人工审核',refundSubmitted:'已提交审核',requestFailed:'请求失败',ORDER_QUERY:'订单查询',PRODUCT_INQUIRY:'商品咨询',REFUND:'退款申请',COMPLAINT:'投诉',OTHER:'其他',SHIPPED:'已发货',PROCESSING:'处理中',DELIVERED:'已送达',CANCELLED:'已取消',PENDING_MANUAL_APPROVAL:'待人工审核',APPROVED_MANUALLY:'已人工批准' },
  en: { title:'Customer Support Workbench',subtitle:'Inquiries · Orders · Refund Review',language:'Language',service:'Business API',online:'Online',offline:'Offline',inquiryTitle:'Handle an Inquiry',inquiryHelp:'Inquiries are classified by rules. No LLM is used.',customerEmail:'Customer email',subject:'Subject',subjectPlaceholder:'Where is my order?',inquiryContent:'Message',inquiryPlaceholder:'Enter the customer message',classify:'Classify and Save',inquirySaved:'Inquiry saved',customerOrders:'Customer and Orders',customerHelp:'Find a customer and their orders by email.',newCustomer:'Add customer',customerName:'Customer name',createCustomer:'Save customer',customerCreated:'Customer created',customerNotFound:'Customer not found',customerAlreadyExists:'This email is already registered',search:'Search',tracking:'Tracking:',notAvailable:'Not available',requestRefund:'Request refund',productLookup:'Product Stock Lookup',skuPlaceholder:'For example, MUG-001',stock:'Stock:',refundTitle:'Refund Request',refundHelp:'This creates a request only. A person must approve any refund.',orderNumber:'Order number',reason:'Reason',reasonPlaceholder:'Describe the reason for the refund',submitReview:'Submit for Review',refundSubmitted:'Submitted for review',requestFailed:'Request failed',ORDER_QUERY:'Order inquiry',PRODUCT_INQUIRY:'Product inquiry',REFUND:'Refund request',COMPLAINT:'Complaint',OTHER:'Other',SHIPPED:'Shipped',PROCESSING:'Processing',DELIVERED:'Delivered',CANCELLED:'Cancelled',PENDING_MANUAL_APPROVAL:'Pending manual approval',APPROVED_MANUALLY:'Manually approved' },
  es: { title:'Panel de Atención al Cliente',subtitle:'Consultas · Pedidos · Revisión de reembolsos',language:'Idioma',service:'Servicio de negocio',online:'En línea',offline:'Desconectado',inquiryTitle:'Gestionar consulta',inquiryHelp:'Las consultas se clasifican mediante reglas, sin usar un LLM.',customerEmail:'Correo del cliente',subject:'Asunto',subjectPlaceholder:'¿Dónde está mi pedido?',inquiryContent:'Mensaje',inquiryPlaceholder:'Escribe el mensaje del cliente',classify:'Clasificar y guardar',inquirySaved:'Consulta guardada',customerOrders:'Cliente y pedidos',customerHelp:'Busca un cliente y sus pedidos por correo.',newCustomer:'Añadir cliente',customerName:'Nombre del cliente',createCustomer:'Guardar cliente',customerCreated:'Cliente creado',customerNotFound:'No se encontró el cliente',customerAlreadyExists:'Este correo ya está registrado',search:'Buscar',tracking:'Seguimiento:',notAvailable:'No disponible',requestRefund:'Solicitar reembolso',productLookup:'Consulta de inventario',skuPlaceholder:'Por ejemplo, MUG-001',stock:'Existencias:',refundTitle:'Solicitud de reembolso',refundHelp:'Esto solo crea una solicitud. Una persona debe aprobar el reembolso.',orderNumber:'Número de pedido',reason:'Motivo',reasonPlaceholder:'Describe el motivo del reembolso',submitReview:'Enviar para revisión',refundSubmitted:'Enviado para revisión',requestFailed:'Error en la solicitud',ORDER_QUERY:'Consulta de pedido',PRODUCT_INQUIRY:'Consulta de producto',REFUND:'Solicitud de reembolso',COMPLAINT:'Queja',OTHER:'Otro',SHIPPED:'Enviado',PROCESSING:'En preparación',DELIVERED:'Entregado',CANCELLED:'Cancelado',PENDING_MANUAL_APPROVAL:'Pendiente de aprobación manual',APPROVED_MANUALLY:'Aprobado manualmente' }
}
const api = axios.create({ baseURL: '/api' })
// Generate a unique key per submission so server-side retries can be handled safely.
api.interceptors.request.use(config => { config.headers['Idempotency-Key'] = config.headers['Idempotency-Key'] || (crypto.randomUUID ? crypto.randomUUID() : `${Date.now()}-${Math.random()}`); return config })
// Unwrap the standard API envelope so view methods work with the domain payload directly.
api.interceptors.response.use(response => {
  const envelope = response.data
  if (envelope && typeof envelope === 'object' && 'status' in envelope && 'data' in envelope) {
    if (envelope.status === 'error') return Promise.reject(new Error(envelope.message || '请求失败'))
    response.data = envelope.data
  }
  return response
})
export default { data: () => ({ locale:localStorage.getItem('order-ai-locale')||'zh',page:'dashboard',menu:[{id:'dashboard',label:'工作台'},{id:'orders',label:'订单管理'},{id:'refunds',label:'退款管理'},{id:'inventory',label:'库存管理'},{id:'inquiries',label:'客户咨询管理'}],filter:'',rows:[],pageNumber:0,totalPages:0,pageSize:10,manageOrderNumber:'',managedOrder:null,manageSku:'',managedProduct:null,managedRefunds:[],health:false,busy:false,error:'',email:'',customer:null,newCustomer:{name:'',email:''},customerCreated:false,orders:[],sku:'',product:null,inquiryResult:null,refundResult:null,form:{customer_email:'',subject:'',body:''},refund:{order_number:'',reason:''} }),
  watch:{locale(value){localStorage.setItem('order-ai-locale',value)}},
  mounted(){api.get('/health').then(()=>{this.health=true}).catch(()=>{})},
  methods:{ t(key){const extra={zh:{dashboard:'工作台',orders:'订单管理',refunds:'退款管理',inventory:'库存管理',inquiries:'客户咨询管理',filter:'筛选当前页',approve:'批准',delete:'删除',previous:'上一页',next:'下一页'},en:{dashboard:'Workbench',orders:'Orders',refunds:'Refunds',inventory:'Inventory',inquiries:'Customer inquiries',filter:'Filter current page',approve:'Approve',delete:'Delete',previous:'Previous',next:'Next'},es:{dashboard:'Panel',orders:'Pedidos',refunds:'Reembolsos',inventory:'Inventario',inquiries:'Consultas',filter:'Filtrar página',approve:'Aprobar',delete:'Eliminar',previous:'Anterior',next:'Siguiente'}};return extra[this.locale]?.[key]||messages[this.locale][key]||key}, async run(fn){this.error='';this.busy=true;try{await fn()}catch(e){this.error=e.response?.data?.detail||e.message||this.t('requestFailed')}finally{this.busy=false}}, openPage(id){this.page=id;this.pageNumber=0;if(id!=='dashboard')this.loadPage(0)}, loadPage(n){return this.run(async()=>{const path={orders:'/orders',refunds:'/refund-requests',inventory:'/products',inquiries:'/inquiries'}[this.page];const result=(await api.get(path,{params:{page:n,size:this.pageSize}})).data;this.rows=result.content||[];this.pageNumber=result.number||0;this.totalPages=result.totalPages||0})}, removeRow(row){return this.run(async()=>{const key=this.page==='orders'?row.order_number:this.page==='inventory'?row.sku:row.id;const path={orders:'/orders',refunds:'/refund-requests',inventory:'/products',inquiries:'/inquiries'}[this.page];await api.delete(`${path}/${encodeURIComponent(key)}`);this.loadPage(this.pageNumber)})}, findOrder(){return this.run(async()=>{this.managedOrder=(await api.get(`/orders/${encodeURIComponent(this.manageOrderNumber)}`)).data})}, findManagedProduct(){return this.run(async()=>{this.managedProduct=(await api.get(`/products/${encodeURIComponent(this.manageSku)}`)).data})}, loadRefunds(){return this.loadPage(0)}, approveRefund(id){return this.run(async()=>{await api.post(`/refund-requests/${id}/approve`);this.loadPage(this.pageNumber)})},
    classify(){return this.run(async()=>{this.inquiryResult=(await api.post('/inquiries',this.form)).data})},
    lookupCustomer(){return this.run(async()=>{this.customerCreated=false;this.customer=null;this.orders=[];try{this.customer=(await api.get(`/customers/by-email/${encodeURIComponent(this.email)}`)).data;this.orders=(await api.get(`/customers/by-email/${encodeURIComponent(this.email)}/orders`)).data}catch(e){if(e.message==='Customer not found')throw new Error(this.t('customerNotFound'));throw e}})},
    createCustomer(){return this.run(async()=>{try{const saved=(await api.post('/customers',this.newCustomer)).data;this.customer=saved;this.email=saved.email;this.orders=[];this.customerCreated=true;this.newCustomer={name:'',email:''}}catch(e){if(e.response?.status===409)throw new Error(this.t('customerAlreadyExists'));throw e}})},
    lookupProduct(){return this.run(async()=>{this.product=(await api.get(`/products/${encodeURIComponent(this.sku)}`)).data})},
    prepareRefund(o){this.refund.order_number=o.order_number;window.scrollTo({top:document.body.scrollHeight,behavior:'smooth'})},
    createRefund(){return this.run(async()=>{this.refundResult=(await api.post('/refund-requests',this.refund)).data})}
  }
}
</script>
<style>
*{box-sizing:border-box}body{margin:0;background:#f3f5f8;color:#172033;font:15px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.shell{max-width:1180px;margin:auto;padding:40px 28px}header{display:flex;justify-content:space-between;align-items:center;margin-bottom:28px}.header-actions{display:flex;align-items:center;gap:12px}.language-label{display:flex;align-items:center;gap:8px;margin:0;color:#536174}.language-label select{padding:8px;border:1px solid #dce1e9;border-radius:8px;background:white;color:#172033;font:inherit}header small{letter-spacing:.13em;color:#718096;font-weight:700}h1{font-size:32px;margin:6px 0 0}header p,.muted{color:#788397;margin:4px 0 16px}.status{background:#fff;padding:9px 14px;border-radius:30px;color:#536174}.status i{display:inline-block;width:8px;height:8px;background:#30b77a;border-radius:50%;margin-right:7px}.menu{display:flex;gap:8px;overflow:auto;margin:0 0 20px;padding:5px 0}.menu button{white-space:nowrap;background:#e7ebf3;color:#536174}.menu button.active{background:#325fcb;color:white}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.card{background:white;border:1px solid #e7eaf0;border-radius:14px;padding:24px;box-shadow:0 4px 16px #1c31500a}.card h2{font-size:19px;margin:0 0 5px}.management{min-height:300px}.inquiry{grid-row:span 2}label{display:block;font-size:13px;font-weight:650;margin:14px 0;color:#48556b}input,textarea{display:block;width:100%;margin-top:6px;padding:11px 12px;border:1px solid #dce1e9;border-radius:8px;font:inherit;background:#fff;color:#172033}input:focus,textarea:focus{outline:2px solid #bcd1ff;border-color:#5c86e8}.row{display:flex;gap:8px;margin-top:14px}.row input{margin:0}button{border:0;border-radius:8px;background:#325fcb;color:white;padding:11px 16px;font-weight:650;cursor:pointer}button:disabled{opacity:.55}.secondary{background:#eaf0ff;color:#315bb5}.warm{background:#bd6b2a}.result,.order{margin-top:14px;padding:14px;background:#f7f9fc;border-radius:9px}.customer-form{margin-top:18px;padding-top:14px;border-top:1px solid #e7eaf0}.customer-form h3{margin:0;color:#35445c;font-size:15px}.tag{display:inline-block;padding:3px 9px;border-radius:30px;background:#e4edff;color:#345cb4;font-size:12px;font-weight:700}.pending{background:#fff1da;color:#99611e}.order span{float:right;color:#4167bc}.order div{color:#66748a;font-size:13px}.link{background:transparent;color:#315bb5;padding:5px 0}.toast{position:fixed;bottom:20px;right:20px;background:#9e2c32;color:white;padding:14px 20px;border-radius:9px}@media(max-width:720px){.shell{padding:24px 14px}.grid{grid-template-columns:1fr}.inquiry{grid-row:auto}header{align-items:flex-start;gap:10px;flex-direction:column}.header-actions{flex-wrap:wrap}}
</style>
